CREATE EXTENSION IF NOT EXISTS pgcrypto;
-- Better Auth core and TOTP schema (camelCase columns are library-owned).
CREATE TABLE "user" (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, "emailVerified" boolean NOT NULL DEFAULT false, image text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), "twoFactorEnabled" boolean DEFAULT false, suspended boolean NOT NULL DEFAULT false);
CREATE TABLE session (id text PRIMARY KEY, "expiresAt" timestamptz NOT NULL, token text NOT NULL UNIQUE, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), "ipAddress" text, "userAgent" text, "userId" text NOT NULL REFERENCES "user"(id));
CREATE TABLE account (id text PRIMARY KEY, "accountId" text NOT NULL, "providerId" text NOT NULL, "userId" text NOT NULL REFERENCES "user"(id), "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, scope text, password text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, "expiresAt" timestamptz NOT NULL, "createdAt" timestamptz DEFAULT now(), "updatedAt" timestamptz DEFAULT now());
CREATE TABLE "twoFactor" (id text PRIMARY KEY, secret text NOT NULL, "backupCodes" text NOT NULL, "userId" text NOT NULL REFERENCES "user"(id), verified boolean DEFAULT false, UNIQUE("userId"));
CREATE TABLE organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, type text NOT NULL CHECK(type IN ('LUX','FACILITY','INSURER','ORANGE')), status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','ACTIVE','SUSPENDED')), demo boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL REFERENCES "user"(id), organization_id uuid NOT NULL REFERENCES organizations(id), roles text[] NOT NULL, status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','REVOKED')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,organization_id));
CREATE INDEX membership_access ON memberships(user_id,status,organization_id);
CREATE TABLE invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), email text NOT NULL, roles text[] NOT NULL, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, accepted_at timestamptz, created_by text NOT NULL REFERENCES "user"(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE enquiries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL, organization text NOT NULL, name text NOT NULL, email text NOT NULL, phone text NOT NULL, location text NOT NULL, message text NOT NULL, consent boolean NOT NULL CHECK(consent), status text NOT NULL DEFAULT 'NEW', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organization_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), enquiry_id uuid NOT NULL UNIQUE REFERENCES enquiries(id), status text NOT NULL DEFAULT 'PENDING', reviewed_by text REFERENCES "user"(id), reason text, organization_id uuid REFERENCES organizations(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE facility_insurer_contracts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), facility_id uuid NOT NULL REFERENCES organizations(id), insurer_id uuid NOT NULL REFERENCES organizations(id), starts_on date NOT NULL, ends_on date NOT NULL, required_documents text[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'ACTIVE', CHECK(facility_id<>insurer_id), CHECK(ends_on>=starts_on));
CREATE TABLE wallet_destinations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), reference text NOT NULL, verified boolean NOT NULL DEFAULT false, version int NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE destination_changes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), proposed_reference text NOT NULL, maker_id text NOT NULL REFERENCES "user"(id), checker_id text REFERENCES "user"(id), reason text NOT NULL, status text NOT NULL DEFAULT 'PENDING', created_at timestamptz NOT NULL DEFAULT now(), CHECK(checker_id IS NULL OR maker_id<>checker_id));
CREATE TABLE patients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), facility_id uuid NOT NULL REFERENCES organizations(id), display_name text NOT NULL, birth_year int CHECK(birth_year BETWEEN 1900 AND 2200), processing_basis text NOT NULL, created_by text REFERENCES "user"(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE patient_corrections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES patients(id), reason text NOT NULL, previous_value jsonb NOT NULL, new_value jsonb NOT NULL, actor_id text NOT NULL REFERENCES "user"(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE insurer_patient_references (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES patients(id), insurer_id uuid NOT NULL REFERENCES organizations(id), external_reference text NOT NULL, policy_reference text NOT NULL, status text NOT NULL, effective_from date NOT NULL, effective_to date NOT NULL, source_updated_at timestamptz NOT NULL, benefits jsonb NOT NULL DEFAULT '{}', UNIQUE(insurer_id,external_reference));
CREATE TABLE eligibility_snapshots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES patients(id), facility_id uuid NOT NULL REFERENCES organizations(id), insurer_id uuid NOT NULL REFERENCES organizations(id), status text NOT NULL CHECK(status IN ('ACTIVE','INACTIVE','STALE','UNKNOWN','UNAVAILABLE')), source text NOT NULL, policy_reference text, checked_at timestamptz NOT NULL DEFAULT now(), source_updated_at timestamptz, benefits jsonb NOT NULL DEFAULT '{}', checked_by text NOT NULL REFERENCES "user"(id));
CREATE TABLE encounters (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES patients(id), facility_id uuid NOT NULL REFERENCES organizations(id), clinician_id text NOT NULL REFERENCES "user"(id), service_date date NOT NULL, diagnosis text NOT NULL, notes text NOT NULL, prescription jsonb NOT NULL DEFAULT '[]', version int NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE encounter_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), encounter_id uuid NOT NULL REFERENCES encounters(id), version int NOT NULL, snapshot jsonb NOT NULL, actor_id text NOT NULL REFERENCES "user"(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(encounter_id,version));
CREATE TABLE tariff_sets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), insurer_id uuid NOT NULL REFERENCES organizations(id), version int NOT NULL, effective_from date NOT NULL, effective_to date NOT NULL, label text NOT NULL, UNIQUE(insurer_id,version));
CREATE TABLE tariff_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tariff_set_id uuid NOT NULL REFERENCES tariff_sets(id), code text NOT NULL, description text NOT NULL, currency text NOT NULL CHECK(currency IN ('USD','LRD')), max_unit_minor bigint NOT NULL CHECK(max_unit_minor>=0), UNIQUE(tariff_set_id,code,currency));
CREATE TABLE coverage_rulesets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), insurer_id uuid NOT NULL REFERENCES organizations(id), version int NOT NULL, rules jsonb NOT NULL, effective_from date NOT NULL, UNIQUE(insurer_id,version));
CREATE TABLE claims (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference text NOT NULL UNIQUE DEFAULT ('LHP-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))), facility_id uuid NOT NULL REFERENCES organizations(id), insurer_id uuid NOT NULL REFERENCES organizations(id), contract_id uuid NOT NULL REFERENCES facility_insurer_contracts(id), patient_id uuid NOT NULL REFERENCES patients(id), encounter_id uuid NOT NULL REFERENCES encounters(id), eligibility_id uuid NOT NULL REFERENCES eligibility_snapshots(id), currency text NOT NULL CHECK(currency IN ('USD','LRD')), state text NOT NULL DEFAULT 'DRAFT' CHECK(state IN ('DRAFT','SUBMITTED','VALIDATING','AWAITING_REVIEW','NEEDS_INFORMATION','APPROVED','PARTIALLY_APPROVED','REJECTED','WITHDRAWN')), submitted_minor bigint NOT NULL CHECK(submitted_minor>=0), approved_minor bigint NOT NULL DEFAULT 0 CHECK(approved_minor>=0 AND approved_minor<=submitted_minor), version int NOT NULL DEFAULT 1, submission_version int NOT NULL DEFAULT 0, created_by text NOT NULL REFERENCES "user"(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX facility_claim_queue ON claims(facility_id,updated_at DESC,id);
CREATE INDEX insurer_claim_queue ON claims(insurer_id,state,updated_at DESC,id);
CREATE TABLE claim_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), claim_id uuid NOT NULL REFERENCES claims(id), code text NOT NULL, description text NOT NULL, quantity int NOT NULL CHECK(quantity>0), unit_minor bigint NOT NULL CHECK(unit_minor>=0));
CREATE TABLE claim_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), claim_id uuid NOT NULL REFERENCES claims(id), version int NOT NULL, snapshot jsonb NOT NULL, actor_id text NOT NULL REFERENCES "user"(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(claim_id,version));
CREATE TABLE attachments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), claim_id uuid NOT NULL REFERENCES claims(id), object_key text NOT NULL UNIQUE, document_type text NOT NULL, content_type text NOT NULL, size_bytes int NOT NULL CHECK(size_bytes BETWEEN 1 AND 10485760), sha256 text, scan_state text NOT NULL DEFAULT 'QUARANTINED' CHECK(scan_state IN ('QUARANTINED','CLEAN','REJECTED','SCAN_ERROR')), uploaded_by text NOT NULL REFERENCES "user"(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE validation_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), claim_id uuid NOT NULL REFERENCES claims(id), input_version int NOT NULL, ruleset_version text NOT NULL, model_version text NOT NULL, status text NOT NULL, processing_error text, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE findings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), validation_run_id uuid NOT NULL REFERENCES validation_runs(id), field text NOT NULL, category text NOT NULL, severity text NOT NULL, reason text NOT NULL, evidence text NOT NULL, confidence numeric, resolution text, resolved_by text REFERENCES "user"(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE review_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), claim_id uuid NOT NULL REFERENCES claims(id), reviewer_id text NOT NULL REFERENCES "user"(id), assigned_by text NOT NULL REFERENCES "user"(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), claim_id uuid NOT NULL REFERENCES claims(id), submission_version int NOT NULL, outcome text NOT NULL, reason text NOT NULL, approved_minor bigint NOT NULL CHECK(approved_minor>=0), tariff_snapshot jsonb NOT NULL, actor_id text NOT NULL REFERENCES "user"(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE appeals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), claim_id uuid NOT NULL REFERENCES claims(id), decision_id uuid NOT NULL REFERENCES decisions(id), reason text NOT NULL, status text NOT NULL DEFAULT 'OPEN', resolution text, created_by text NOT NULL REFERENCES "user"(id), reviewed_by text REFERENCES "user"(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE fee_policies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), insurer_id uuid NOT NULL REFERENCES organizations(id), version int NOT NULL, mode text NOT NULL CHECK(mode IN ('UNCONFIGURED','INSURER_ADDED','FACILITY_DEDUCTED')), collection_supported boolean NOT NULL DEFAULT false, approved_by text REFERENCES "user"(id), effective_at timestamptz NOT NULL, UNIQUE(insurer_id,version));
CREATE TABLE payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), claim_id uuid NOT NULL REFERENCES claims(id), facility_id uuid NOT NULL REFERENCES organizations(id), insurer_id uuid NOT NULL REFERENCES organizations(id), currency text NOT NULL CHECK(currency IN ('USD','LRD')), base_minor bigint NOT NULL CHECK(base_minor>0), state text NOT NULL CHECK(state IN ('CREATED','AWAITING_AUTHORIZATION','AUTHORIZED','AWAITING_FUNDS','PROCESSING','UNKNOWN_PENDING_INVESTIGATION','SETTLED','FAILED','CANCELLED','REVERSED')), mode text NOT NULL CHECK(mode IN ('demo','manual','sandbox','live')), destination_snapshot jsonb NOT NULL, fee_snapshot jsonb NOT NULL, policy_id uuid NOT NULL REFERENCES fee_policies(id), provider_reference text UNIQUE, version int NOT NULL DEFAULT 1, created_by text NOT NULL REFERENCES "user"(id), created_at timestamptz NOT NULL DEFAULT now(), settled_at timestamptz);
CREATE INDEX payment_queue ON payments(insurer_id,state,created_at);
CREATE TABLE payment_authorizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_id uuid NOT NULL UNIQUE REFERENCES payments(id), maker_id text NOT NULL REFERENCES "user"(id), checker_id text REFERENCES "user"(id), reason text NOT NULL, authorized_at timestamptz, CHECK(checker_id IS NULL OR checker_id<>maker_id));
CREATE TABLE claim_payment_allocations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), claim_id uuid NOT NULL REFERENCES claims(id), payment_id uuid NOT NULL UNIQUE REFERENCES payments(id), amount_minor bigint NOT NULL CHECK(amount_minor>0), status text NOT NULL CHECK(status IN ('RESERVED','CONFIRMED','RELEASED','REVERSED')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_id uuid NOT NULL REFERENCES payments(id), idempotency_key text NOT NULL UNIQUE, status text NOT NULL, external_reference text UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE provider_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_event_id text NOT NULL UNIQUE, payment_id uuid NOT NULL REFERENCES payments(id), payload_hash text NOT NULL, verified boolean NOT NULL CHECK(verified), outcome text NOT NULL, evidence jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE fee_assessments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_id uuid NOT NULL UNIQUE REFERENCES payments(id), currency text NOT NULL, total_minor bigint NOT NULL, lux_minor bigint NOT NULL, orange_minor bigint NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK(total_minor=lux_minor+orange_minor));
CREATE TABLE ledger_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_id uuid NOT NULL REFERENCES payments(id), category text NOT NULL, currency text NOT NULL, amount_minor bigint NOT NULL, evidence_id uuid NOT NULL REFERENCES provider_events(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(payment_id,category));
CREATE TABLE fee_settlement_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), assessment_id uuid NOT NULL REFERENCES fee_assessments(id), beneficiary text NOT NULL CHECK(beneficiary IN ('LUX','ORANGE')), amount_minor bigint NOT NULL CHECK(amount_minor>0), verified_reference text NOT NULL UNIQUE, verified_by text NOT NULL REFERENCES "user"(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reconciliation_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), checksum text NOT NULL, source text NOT NULL, status text NOT NULL, rows jsonb NOT NULL, created_by text NOT NULL REFERENCES "user"(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,checksum));
CREATE TABLE reconciliation_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), run_id uuid REFERENCES reconciliation_runs(id), payment_id uuid REFERENCES payments(id), category text NOT NULL, status text NOT NULL DEFAULT 'OPEN', owner_id text REFERENCES "user"(id), notes text, evidence text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reconciliation_resolutions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), item_id uuid NOT NULL REFERENCES reconciliation_items(id), actor_id text NOT NULL REFERENCES "user"(id), notes text NOT NULL, evidence text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), user_id text REFERENCES "user"(id), event_key text NOT NULL, title text NOT NULL, link text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,event_key));
CREATE TABLE support_tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), subject text NOT NULL, message text NOT NULL, status text NOT NULL DEFAULT 'OPEN', created_by text NOT NULL REFERENCES "user"(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE support_access (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), user_id text NOT NULL REFERENCES "user"(id), reason text NOT NULL, approved_by text NOT NULL REFERENCES "user"(id), expires_at timestamptz NOT NULL, CHECK(user_id<>approved_by));
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid REFERENCES organizations(id), actor_id text REFERENCES "user"(id), action text NOT NULL, resource_id text, metadata jsonb NOT NULL DEFAULT '{}', correlation_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_org_time ON audit_events(organization_id,created_at DESC);
CREATE TABLE outbox_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), type text NOT NULL, organization_id uuid NOT NULL REFERENCES organizations(id), resource_id uuid NOT NULL, payload jsonb NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'PENDING', attempts int NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), locked_at timestamptz, last_error text, created_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz);
CREATE INDEX outbox_pending ON outbox_events(status,available_at);
CREATE TABLE idempotency_commands (organization_id uuid NOT NULL REFERENCES organizations(id), actor_id text NOT NULL REFERENCES "user"(id), key text NOT NULL, fingerprint text NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(organization_id,actor_id,key));
CREATE TABLE public_pages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL, version int NOT NULL, status text NOT NULL CHECK(status IN ('DRAFT','PUBLISHED')), content jsonb NOT NULL, edited_by text REFERENCES "user"(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(slug,version));
CREATE TABLE team_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, name text NOT NULL, role text NOT NULL, bio text, photo text, alt text, sort_order int NOT NULL, published boolean NOT NULL DEFAULT false, admin_note text, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE partner_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, status text NOT NULL, permission_to_display boolean NOT NULL DEFAULT false, logo text, description text NOT NULL, published boolean NOT NULL DEFAULT false, CHECK(NOT published OR (permission_to_display AND logo IS NOT NULL AND status='CONFIRMED')));
CREATE TABLE media_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), key text NOT NULL UNIQUE, path text NOT NULL, alt text NOT NULL, provenance text NOT NULL, approved boolean NOT NULL DEFAULT false, focal_x int DEFAULT 50, focal_y int DEFAULT 50);
CREATE TABLE integration_configurations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), provider text NOT NULL, mode text NOT NULL, capabilities jsonb NOT NULL DEFAULT '{}', enabled boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rate_limits (key text PRIMARY KEY, window_start timestamptz NOT NULL DEFAULT now(), count int NOT NULL DEFAULT 1);
-- Financial/submitted/audit evidence is append-only. Retention is a separately approved operation.
CREATE FUNCTION immutable_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable record'; END $$;
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER versions_immutable BEFORE UPDATE OR DELETE ON claim_versions FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER decisions_immutable BEFORE UPDATE OR DELETE ON decisions FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER ledger_immutable BEFORE UPDATE OR DELETE ON ledger_entries FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER provider_immutable BEFORE UPDATE OR DELETE ON provider_events FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER fees_immutable BEFORE UPDATE OR DELETE ON fee_assessments FOR EACH ROW EXECUTE FUNCTION immutable_record();
